files.content:
.root { display: grid; width: 100%; min-width: 0; color: var(--foreground); }
.input { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; clip-path: inset(50%); }
/* A full-width drop target: press feedback is color only, never a scale. */
.dropzone { display: flex; min-height: 92px; align-items: center; gap: 12px; padding: 16px; border: 1px dashed var(--border-strong); border-radius: var(--radius-panel); background: var(--surface); cursor: pointer; transition: border-color var(--duration-standard) var(--ease-standard), background-color var(--duration-standard) var(--ease-standard); }
.dropzone.dragging, .dropzone:not(.disabled):active { border-color: var(--accent); background: var(--accent-subtle); }
.dropzone:focus-visible { outline: 3px solid var(--focus-ring); outline-offset: 3px; }
.dropzone.disabled { cursor: not-allowed; opacity: .52; }
.uploadIcon, .fileIcon { display: grid; flex: 0 0 auto; place-items: center; color: var(--accent-strong); }
/* The cloud lifts toward the file while it hovers over the drop target. */
.uploadIcon { width: 24px; height: 24px; transition: transform var(--duration-spring) var(--ease-spring); }
.dragging .uploadIcon { transform: translateY(-3px); }
.copy { display: grid; min-width: 0; gap: 3px; flex: 1; }
.copy strong { font-size: var(--text-sm); font-weight: 500; }
.label { position: relative; display: block; min-width: 0; }
.labelText { display: block; }
.copy > span { color: var(--text-muted); font-size: var(--text-xs); line-height: 1.4; overflow-wrap: anywhere; }
.browse { flex: 0 0 auto; color: var(--accent-strong); font-size: var(--text-xs); font-weight: 500; }
.statusFrame { overflow: hidden; }
.status { position: relative; min-height: 16px; margin: 0; padding-top: 8px; color: var(--text-muted); font-size: var(--text-xs); }
.statusText { display: block; }
.fileList { display: grid; margin: 0; padding: 0; list-style: none; }
/* The gap lives inside the clipped row, so a collapsing row reaches zero height instead of stopping at its padding. */
.fileRow { overflow: hidden; }
.fileItem { display: flex; margin-top: 6px; min-width: 0; align-items: center; gap: 9px; padding: 9px 10px; border: 1px solid var(--border-subtle); border-radius: var(--radius-control); background: var(--surface-muted); }
.fileIcon { width: 24px; height: 24px; color: var(--text-secondary); }
.fileCopy { display: grid; min-width: 0; flex: 1; gap: 2px; }
.fileCopy strong { overflow: hidden; font-size: var(--text-xs); font-weight: 500; text-overflow: ellipsis; white-space: nowrap; }
.fileCopy > span { color: var(--text-muted); font-size: 11px; }
.meta { display: flex; min-width: 0; white-space: nowrap; font-variant-numeric: tabular-nums; }
.phase { position: relative; display: inline-block; }
.phaseText { display: block; }
.percent { display: inline-block; min-width: 4ch; }
.fileCopy .error { color: var(--danger); }
.barFrame { display: block; }
.bar { display: block; height: 3px; margin: 5px 0 1px; overflow: hidden; border-radius: 99px; background: var(--border); }
.barFill { display: block; width: 100%; height: 100%; border-radius: inherit; background: var(--accent); }
.statusSlot { position: relative; display: grid; width: 26px; height: 26px; flex: 0 0 auto; place-items: center; }
.retrySlot { display: grid; place-items: center; }
.ready { display: grid; width: 22px; height: 22px; place-items: center; color: var(--success); }
.remove, .retry { display: grid; width: 26px; height: 26px; flex: 0 0 auto; place-items: center; border: 0; border-radius: var(--radius-pill); background: transparent; color: var(--text-muted); cursor: pointer; transition: transform var(--duration-spring) var(--ease-spring), background-color var(--duration-fast) var(--ease-standard), color var(--duration-fast) var(--ease-standard); }
.retry { color: var(--danger); }
/* Quick press, spring release. */
.remove:active, .retry:active { transform: scale(.96); transition-duration: var(--duration-instant); transition-timing-function: var(--ease-standard); }
.remove:focus-visible, .retry:focus-visible { outline: 3px solid var(--focus-ring); outline-offset: 2px; }
@media (hover: hover) and (pointer: fine) {
  .dropzone:not(.disabled):hover { border-color: var(--accent); background: var(--accent-subtle); }
  .remove:hover, .retry:hover { background: var(--surface); color: var(--foreground); }
}
.srOnly { position: absolute; width: 1px; height: 1px; padding: 0; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0; }
@media (prefers-reduced-motion: reduce) { .dropzone, .uploadIcon, .remove, .retry { transition: none; } .dragging .uploadIcon, .remove:active, .retry:active { transform: none; } }
